/** static void DrawExperienceProgressBar(struct Pokemon *unused) */
export function DrawExperienceProgressBar(unused: any): any {
  let numExpProgressBarTicks: any = null;
      let summary: any =sMonSummaryScreen.summary;
      let dst: any = null;
      let i: any = null;

      if (summary.level < MAX_LEVEL)
      {
          let expBetweenLevels: any = gExperienceTables[gSpeciesInfo[summary.species].growthRate][summary.level + 1] - gExperienceTables[gSpeciesInfo[summary.species].growthRate][summary.level];
          let expSinceLastLevel: any = summary.exp - gExperienceTables[gSpeciesInfo[summary.species].growthRate][summary.level];

           
           
           
          numExpProgressBarTicks = expSinceLastLevel * 64 / expBetweenLevels;
          if (numExpProgressBarTicks == 0 && expSinceLastLevel != 0)
              numExpProgressBarTicks = 1;
      }
      else
      {
          numExpProgressBarTicks = 0;
      }

      dst =sMonSummaryScreen.bgTilemapBuffers[PSS_PAGE_SKILLS][1][_0x255];
      for (i = 0; i < 8; i++)
      {
          if (numExpProgressBarTicks > 7)
              dst[i] = 0x206A;
          else
              dst[i] = _0x2062 + (numExpProgressBarTicks % 8);
          numExpProgressBarTicks -= 8;
          if (numExpProgressBarTicks < 0)
              numExpProgressBarTicks = 0;
      }

      if (GetBgTilemapBuffer(1) == sMonSummaryScreen.bgTilemapBuffers[PSS_PAGE_SKILLS][0])
          ScheduleBgCopyTilemapToVram(1);
      else
          ScheduleBgCopyTilemapToVram(2);
}

/** static void DrawContestMoveHearts(u16 move) */
export function DrawContestMoveHearts(move: any): any {
  let tilemap: any = sMonSummaryScreen.bgTilemapBuffers[PSS_PAGE_CONTEST_MOVES][1];
      let i: any = null;

      if (move != MOVE_NONE)
      {
           
          let effectValue: any = gContestEffects[gContestMoves[move].effect].appeal;
          if (effectValue != 0xFF)
              effectValue /= 10;

          for (i = 0; i < MAX_CONTEST_MOVE_HEARTS; i++)
          {
              if (effectValue != 0xFF && i < effectValue)
                  tilemap[(i / 4 * 32) + (i & 3) + 0x1E6] = TILE_FILLED_APPEAL_HEART;
              else
                  tilemap[(i / 4 * 32) + (i & 3) + 0x1E6] = TILE_EMPTY_APPEAL_HEART;
          }

           
          effectValue = gContestEffects[gContestMoves[move].effect].jam;
          if (effectValue != 0xFF)
              effectValue /= 10;

          for (i = 0; i < MAX_CONTEST_MOVE_HEARTS; i++)
          {
              if (effectValue != 0xFF && i < effectValue)
                  tilemap[(i / 4 * 32) + (i & 3) + _0x226] = TILE_FILLED_JAM_HEART;
              else
                  tilemap[(i / 4 * 32) + (i & 3) + _0x226] = TILE_EMPTY_JAM_HEART;
          }
      }
}

