/** static void PutPageWindowTilemaps(u8 page) */
export function PutPageWindowTilemaps(page: any): any {
  let i: any = null;

      ClearWindowTilemap(PSS_LABEL_WINDOW_POKEMON_INFO_TITLE);
      ClearWindowTilemap(PSS_LABEL_WINDOW_POKEMON_SKILLS_TITLE);
      ClearWindowTilemap(PSS_LABEL_WINDOW_BATTLE_MOVES_TITLE);
      ClearWindowTilemap(PSS_LABEL_WINDOW_CONTEST_MOVES_TITLE);

      switch (page)
      {
      case PSS_PAGE_INFO:
          PutWindowTilemap(PSS_LABEL_WINDOW_POKEMON_INFO_TITLE);
          PutWindowTilemap(PSS_LABEL_WINDOW_PROMPT_CANCEL);
          if (InBattleFactory() == TRUE || InSlateportBattleTent() == TRUE)
              PutWindowTilemap(PSS_LABEL_WINDOW_POKEMON_INFO_RENTAL);
          PutWindowTilemap(PSS_LABEL_WINDOW_POKEMON_INFO_TYPE);
          break;
      case PSS_PAGE_SKILLS:
          PutWindowTilemap(PSS_LABEL_WINDOW_POKEMON_SKILLS_TITLE);
          PutWindowTilemap(PSS_LABEL_WINDOW_POKEMON_SKILLS_STATS_LEFT);
          PutWindowTilemap(PSS_LABEL_WINDOW_POKEMON_SKILLS_STATS_RIGHT);
          PutWindowTilemap(PSS_LABEL_WINDOW_POKEMON_SKILLS_EXP);
          break;
      case PSS_PAGE_BATTLE_MOVES:
          PutWindowTilemap(PSS_LABEL_WINDOW_BATTLE_MOVES_TITLE);
          if (sMonSummaryScreen.mode == SUMMARY_MODE_SELECT_MOVE)
          {
              if (sMonSummaryScreen.newMove != MOVE_NONE || sMonSummaryScreen.firstMoveIndex != MAX_MON_MOVES)
                  PutWindowTilemap(PSS_LABEL_WINDOW_MOVES_POWER_ACC);
          }
          else
          {
              PutWindowTilemap(PSS_LABEL_WINDOW_PROMPT_INFO);
          }
          break;
      case PSS_PAGE_CONTEST_MOVES:
          PutWindowTilemap(PSS_LABEL_WINDOW_CONTEST_MOVES_TITLE);
          if (sMonSummaryScreen.mode == SUMMARY_MODE_SELECT_MOVE)
          {
              if (sMonSummaryScreen.newMove != MOVE_NONE || sMonSummaryScreen.firstMoveIndex != MAX_MON_MOVES)
                  PutWindowTilemap(PSS_LABEL_WINDOW_MOVES_APPEAL_JAM);
          }
          else
          {
              PutWindowTilemap(PSS_LABEL_WINDOW_PROMPT_INFO);
          }
          break;
      }

      for (i = 0; i < ARRAY_COUNT(sMonSummaryScreen.windowIds); i++)
          PutWindowTilemap(sMonSummaryScreen.windowIds[i]);

      ScheduleBgCopyTilemapToVram(0);
}

/** static void ClearPageWindowTilemaps(u8 page) */
export function ClearPageWindowTilemaps(page: any): any {
  let i: any = null;

      switch (page)
      {
      case PSS_PAGE_INFO:
          ClearWindowTilemap(PSS_LABEL_WINDOW_PROMPT_CANCEL);
          if (InBattleFactory() == TRUE || InSlateportBattleTent() == TRUE)
              ClearWindowTilemap(PSS_LABEL_WINDOW_POKEMON_INFO_RENTAL);
          ClearWindowTilemap(PSS_LABEL_WINDOW_POKEMON_INFO_TYPE);
          break;
      case PSS_PAGE_SKILLS:
          ClearWindowTilemap(PSS_LABEL_WINDOW_POKEMON_SKILLS_STATS_LEFT);
          ClearWindowTilemap(PSS_LABEL_WINDOW_POKEMON_SKILLS_STATS_RIGHT);
          ClearWindowTilemap(PSS_LABEL_WINDOW_POKEMON_SKILLS_EXP);
          break;
      case PSS_PAGE_BATTLE_MOVES:
          if (sMonSummaryScreen.mode == SUMMARY_MODE_SELECT_MOVE)
          {
              if (sMonSummaryScreen.newMove != MOVE_NONE || sMonSummaryScreen.firstMoveIndex != MAX_MON_MOVES)
                  ClearWindowTilemap(PSS_LABEL_WINDOW_MOVES_POWER_ACC);
          }
          else
          {
              ClearWindowTilemap(PSS_LABEL_WINDOW_PROMPT_INFO);
          }
          break;
      case PSS_PAGE_CONTEST_MOVES:
          if (sMonSummaryScreen.mode == SUMMARY_MODE_SELECT_MOVE)
          {
              if (sMonSummaryScreen.newMove != MOVE_NONE || sMonSummaryScreen.firstMoveIndex != MAX_MON_MOVES)
                  ClearWindowTilemap(PSS_LABEL_WINDOW_MOVES_APPEAL_JAM);
          }
          else
          {
              ClearWindowTilemap(PSS_LABEL_WINDOW_PROMPT_INFO);
          }
          break;
      }

      for (i = 0; i < ARRAY_COUNT(sMonSummaryScreen.windowIds); i++)
          RemoveWindowByIndex(i);

      ScheduleBgCopyTilemapToVram(0);
}

/** static u8 AddWindowFromTemplateList(const struct WindowTemplate *template, u8 templateId) */
export function AddWindowFromTemplateList(template: any, templateId: any): any {
  let windowIdPtr: any =sMonSummaryScreen.windowIds[templateId];
      if (windowIdPtr == WINDOW_NONE)
      {
          windowIdPtr = AddWindow(template[templateId]);
          FillWindowPixelBuffer(windowIdPtr, PIXEL_FILL(0));
      }
      return windowIdPtr;
}

/** static void RemoveWindowByIndex(u8 windowIndex) */
export function RemoveWindowByIndex(windowIndex: any): any {
  let windowIdPtr: any =sMonSummaryScreen.windowIds[windowIndex];
      if (windowIdPtr != WINDOW_NONE)
      {
          ClearWindowTilemap(windowIdPtr);
          RemoveWindow(windowIdPtr);
          windowIdPtr = WINDOW_NONE;
      }
}

/** static void PrintPageSpecificText(u8 pageIndex) */
export function PrintPageSpecificText(pageIndex: any): any {
  let i: any = null;
      for (i = 0; i < ARRAY_COUNT(sMonSummaryScreen.windowIds); i++)
      {
          if (sMonSummaryScreen.windowIds[i] != WINDOW_NONE)
              FillWindowPixelBuffer(sMonSummaryScreen.windowIds[i], PIXEL_FILL(0));
      }
      sTextPrinterFunctions[pageIndex]();
}

