/** static void SetMonTypeIcons(void) */
export function SetMonTypeIcons(): any {
  let summary: any =sMonSummaryScreen.summary;
      if (summary.isEgg)
      {
          SetTypeSpritePosAndPal(TYPE_MYSTERY, 120, 48, SPRITE_ARR_ID_TYPE);
          SetSpriteInvisibility(SPRITE_ARR_ID_TYPE + 1, TRUE);
      }
      else
      {
          SetTypeSpritePosAndPal(gSpeciesInfo[summary.species].types[0], 120, 48, SPRITE_ARR_ID_TYPE);
          if (gSpeciesInfo[summary.species].types[0] != gSpeciesInfo[summary.species].types[1])
          {
              SetTypeSpritePosAndPal(gSpeciesInfo[summary.species].types[1], 160, 48, SPRITE_ARR_ID_TYPE + 1);
              SetSpriteInvisibility(SPRITE_ARR_ID_TYPE + 1, FALSE);
          }
          else
          {
              SetSpriteInvisibility(SPRITE_ARR_ID_TYPE + 1, TRUE);
          }
      }
}

/** static void SetMoveTypeIcons(void) */
export function SetMoveTypeIcons(): any {
  let i: any = null;
      let summary: any =sMonSummaryScreen.summary;
      for (i = 0; i < MAX_MON_MOVES; i++)
      {
          if (summary.moves[i] != MOVE_NONE)
              SetTypeSpritePosAndPal(gBattleMoves[summary.moves[i]].type, 85, 32 + (i * 16), i + SPRITE_ARR_ID_TYPE);
          else
              SetSpriteInvisibility(i + SPRITE_ARR_ID_TYPE, TRUE);
      }
}

/** static void SetContestMoveTypeIcons(void) */
export function SetContestMoveTypeIcons(): any {
  let i: any = null;
      let summary: any =sMonSummaryScreen.summary;
      for (i = 0; i < MAX_MON_MOVES; i++)
      {
          if (summary.moves[i] != MOVE_NONE)
              SetTypeSpritePosAndPal(NUMBER_OF_MON_TYPES + gContestMoves[summary.moves[i]].contestCategory, 85, 32 + (i * 16), i + SPRITE_ARR_ID_TYPE);
          else
              SetSpriteInvisibility(i + SPRITE_ARR_ID_TYPE, TRUE);
      }
}

/** static void SetNewMoveTypeIcon(void) */
export function SetNewMoveTypeIcon(): any {
  if (sMonSummaryScreen.newMove == MOVE_NONE)
      {
          SetSpriteInvisibility(SPRITE_ARR_ID_TYPE + 4, TRUE);
      }
      else
      {
          if (sMonSummaryScreen.currPageIndex == PSS_PAGE_BATTLE_MOVES)
              SetTypeSpritePosAndPal(gBattleMoves[sMonSummaryScreen.newMove].type, 85, 96, SPRITE_ARR_ID_TYPE + 4);
          else
              SetTypeSpritePosAndPal(NUMBER_OF_MON_TYPES + gContestMoves[sMonSummaryScreen.newMove].contestCategory, 85, 96, SPRITE_ARR_ID_TYPE + 4);
      }
}

/** static void SwapMovesTypeSprites(u8 moveIndex1, u8 moveIndex2) */
export function SwapMovesTypeSprites(moveIndex1: any, moveIndex2: any): any {
  let sprite1: any =gSprites[sMonSummaryScreen.spriteIds[moveIndex1 + SPRITE_ARR_ID_TYPE]];
      let sprite2: any =gSprites[sMonSummaryScreen.spriteIds[moveIndex2 + SPRITE_ARR_ID_TYPE]];

      let temp: any = sprite1.animNum;
      sprite1.animNum = sprite2.animNum;
      sprite2.animNum = temp;

      temp = sprite1.oam.paletteNum;
      sprite1.oam.paletteNum = sprite2.oam.paletteNum;
      sprite2.oam.paletteNum = temp;

      sprite1.animBeginning = TRUE;
      sprite1.animEnded = FALSE;
      sprite2.animBeginning = TRUE;
      sprite2.animEnded = FALSE;
}

/** static u8 LoadMonGfxAndSprite(struct Pokemon *mon, s16 *state) */
export function LoadMonGfxAndSprite(mon: any, state: any): any {
  let pal: any = null;
      let summary: any =sMonSummaryScreen.summary;

      switch (state)
      {
      default:
          return CreateMonSprite(mon);
      case 0:
          if (gMain.inBattle)
          {
              if (ShouldIgnoreDeoxysForm(3, sMonSummaryScreen.curMonIndex))
                  HandleLoadSpecialPokePic_DontHandleDeoxys(gMonFrontPicTable[summary.species2],
                                                            gMonSpritesGfxPtr.sprites.ptr[B_POSITION_OPPONENT_LEFT],
                                                            summary.species2,
                                                            summary.pid);
              else
                  HandleLoadSpecialPokePic_2(gMonFrontPicTable[summary.species2],
                                             gMonSpritesGfxPtr.sprites.ptr[B_POSITION_OPPONENT_LEFT],
                                             summary.species2,
                                             summary.pid);
          }
          else
          {
              if (gMonSpritesGfxPtr != NULL)
              {
                  if (sMonSummaryScreen.monList.mons == gPlayerParty || sMonSummaryScreen.mode == SUMMARY_MODE_BOX || sMonSummaryScreen.handleDeoxys == TRUE)
                      HandleLoadSpecialPokePic_2(gMonFrontPicTable[summary.species2],
                                                 gMonSpritesGfxPtr.sprites.ptr[B_POSITION_OPPONENT_LEFT],
                                                 summary.species2,
                                                 summary.pid);
                  else
                      HandleLoadSpecialPokePic_DontHandleDeoxys(gMonFrontPicTable[summary.species2],
                                                                gMonSpritesGfxPtr.sprites.ptr[B_POSITION_OPPONENT_LEFT],
                                                                summary.species2,
                                                                summary.pid);
              }
              else
              {
                  if (sMonSummaryScreen.monList.mons == gPlayerParty || sMonSummaryScreen.mode == SUMMARY_MODE_BOX || sMonSummaryScreen.handleDeoxys == TRUE)
                      HandleLoadSpecialPokePic_2(gMonFrontPicTable[summary.species2],
                                                  MonSpritesGfxManager_GetSpritePtr(MON_SPR_GFX_MANAGER_A, B_POSITION_OPPONENT_LEFT),
                                                  summary.species2,
                                                  summary.pid);
                  else
                      HandleLoadSpecialPokePic_DontHandleDeoxys(gMonFrontPicTable[summary.species2],
                                                                MonSpritesGfxManager_GetSpritePtr(MON_SPR_GFX_MANAGER_A, B_POSITION_OPPONENT_LEFT),
                                                                summary.species2,
                                                                summary.pid);
              }
          }
          state++;
          return 0xFF;
      case 1:
          pal = GetMonSpritePalStructFromOtIdPersonality(summary.species2, summary.OTID, summary.pid);
          LoadCompressedSpritePalette(pal);
          SetMultiuseSpriteTemplateToPokemon(pal.tag, B_POSITION_OPPONENT_LEFT);
          state++;
          return 0xFF;
      }
}

/** static void PlayMonCry(void) */
export function PlayMonCry(): any {
  let summary: any =sMonSummaryScreen.summary;
      if (!summary.isEgg)
      {
          if (ShouldPlayNormalMonCry(sMonSummaryScreen.currentMon) == TRUE)
              PlayCry_ByMode(summary.species2, 0, CRY_MODE_NORMAL);
          else
              PlayCry_ByMode(summary.species2, 0, CRY_MODE_WEAK);
      }
}

/** static u8 CreateMonSprite(struct Pokemon *unused) */
export function CreateMonSprite(unused: any): any {
  let summary: any =sMonSummaryScreen.summary;
      let spriteId: any = CreateSprite(gMultiuseSpriteTemplate, 40, 64, 5);

      FreeSpriteOamMatrix(gSprites[spriteId]);
      gSprites[spriteId].data[0] = summary.species2;
      gSprites[spriteId].data[2] = 0;
      gSprites[spriteId].callback = SpriteCB_Pokemon;
      gSprites[spriteId].oam.priority = 0;

      if (!IsMonSpriteNotFlipped(summary.species2))
          gSprites[spriteId].hFlip = TRUE;
      else
          gSprites[spriteId].hFlip = FALSE;

      return spriteId;
}

/** static void SpriteCB_Pokemon(struct Sprite *sprite) */
export function SpriteCB_Pokemon(sprite: any): any {
  let summary: any =sMonSummaryScreen.summary;

      if (!gPaletteFade.active && sprite.data[2] != 1)
      {
          sprite.data[1] = IsMonSpriteNotFlipped(sprite.data[0]);
          PlayMonCry();
          PokemonSummaryDoMonAnimation(sprite, sprite.data[0], summary.isEgg);
      }
}

/** void SummaryScreen_SetAnimDelayTaskId(u8 taskId) */
export function SummaryScreen_SetAnimDelayTaskId(taskId: any): any {
  sAnimDelayTaskId = taskId;
}

/** static void SummaryScreen_DestroyAnimDelayTask(void) */
export function SummaryScreen_DestroyAnimDelayTask(): any {
  if (sAnimDelayTaskId != TASK_NONE)
      {
          DestroyTask(sAnimDelayTaskId);
          sAnimDelayTaskId = TASK_NONE;
      }
}

/** static void StopPokemonAnimations(void) */
export function StopPokemonAnimations(): any {
  let i: any = null;
      let paletteIndex: any = null;

      gSprites[sMonSummaryScreen.spriteIds[SPRITE_ARR_ID_MON]].animPaused = TRUE;
      gSprites[sMonSummaryScreen.spriteIds[SPRITE_ARR_ID_MON]].callback = SpriteCallbackDummy;
      StopPokemonAnimationDelayTask();

      paletteIndex = OBJ_PLTT_ID(gSprites[sMonSummaryScreen.spriteIds[SPRITE_ARR_ID_MON]].oam.paletteNum);

      for (i = 0; i < 16; i++)
      {
          let id: any = i + paletteIndex;
          gPlttBufferUnfaded[id] = gPlttBufferFaded[id];
      }
}

/** static void CreateMonMarkingsSprite(struct Pokemon *mon) */
export function CreateMonMarkingsSprite(mon: any): any {
  let sprite: any = CreateMonMarkingAllCombosSprite(TAG_MON_MARKINGS, TAG_MON_MARKINGS, sMarkings_Pal);

      sMonSummaryScreen.markingsSprite = sprite;
      if (sprite != NULL)
      {
          StartSpriteAnim(sprite, GetMonData(mon, MON_DATA_MARKINGS));
          sMonSummaryScreen.markingsSprite.x = 60;
          sMonSummaryScreen.markingsSprite.y = 26;
          sMonSummaryScreen.markingsSprite.oam.priority = 1;
      }
}

/** static void RemoveAndCreateMonMarkingsSprite(struct Pokemon *mon) */
export function RemoveAndCreateMonMarkingsSprite(mon: any): any {
  DestroySprite(sMonSummaryScreen.markingsSprite);
      FreeSpriteTilesByTag(TAG_MON_MARKINGS);
      CreateMonMarkingsSprite(mon);
}

/** static void CreateCaughtBallSprite(struct Pokemon *mon) */
export function CreateCaughtBallSprite(mon: any): any {
  let ball: any = ItemIdToBallId(GetMonData(mon, MON_DATA_POKEBALL));

      LoadBallGfx(ball);
      sMonSummaryScreen.spriteIds[SPRITE_ARR_ID_BALL] = CreateSprite(gBallSpriteTemplates[ball], 16, 136, 0);
      gSprites[sMonSummaryScreen.spriteIds[SPRITE_ARR_ID_BALL]].callback = SpriteCallbackDummy;
      gSprites[sMonSummaryScreen.spriteIds[SPRITE_ARR_ID_BALL]].oam.priority = 3;
}

/** static void CreateSetStatusSprite(void) */
export function CreateSetStatusSprite(): any {
  let spriteId: any =sMonSummaryScreen.spriteIds[SPRITE_ARR_ID_STATUS];
      let statusAnim: any = null;

      if (spriteId == SPRITE_NONE)
          spriteId = CreateSprite(sSpriteTemplate_StatusCondition, 64, 152, 0);

      statusAnim = GetMonAilment(sMonSummaryScreen.currentMon);
      if (statusAnim != 0)
      {
          StartSpriteAnim(gSprites[spriteId], statusAnim - 1);
          SetSpriteInvisibility(SPRITE_ARR_ID_STATUS, FALSE);
      }
      else
      {
          SetSpriteInvisibility(SPRITE_ARR_ID_STATUS, TRUE);
      }
}

/** static void CreateMoveSelectorSprites(u8 idArrayStart) */
export function CreateMoveSelectorSprites(idArrayStart: any): any {
  let i: any = null;
      let spriteIds: any =sMonSummaryScreen.spriteIds[idArrayStart];

      if (sMonSummaryScreen.currPageIndex >= PSS_PAGE_BATTLE_MOVES)
      {
          let subpriority: any = 0;
          if (idArrayStart == SPRITE_ARR_ID_MOVE_SELECTOR1)
              subpriority = 1;

          for (i = 0; i < MOVE_SELECTOR_SPRITES_COUNT; i++)
          {
              spriteIds[i] = CreateSprite(sMoveSelectorSpriteTemplate, i * 16 + 89, 40, subpriority);
              if (i == 0)
                  StartSpriteAnim(gSprites[spriteIds[i]], 4);  
              else if (i == 9)
                  StartSpriteAnim(gSprites[spriteIds[i]], 5);  
              else
                  StartSpriteAnim(gSprites[spriteIds[i]], 6);  

              gSprites[spriteIds[i]].callback = SpriteCB_MoveSelector;
              gSprites[spriteIds[i]].data[0] = idArrayStart;
              gSprites[spriteIds[i]].data[1] = 0;
          }
      }
}

/** static void SpriteCB_MoveSelector(struct Sprite *sprite) */
export function SpriteCB_MoveSelector(sprite: any): any {
  if (sprite.animNum > 3 && sprite.animNum < 7)
      {
          sprite.data[1] = (sprite.data[1] + 1) & 0x1F;
          if (sprite.data[1] > 24)
              sprite.invisible = TRUE;
          else
              sprite.invisible = FALSE;
      }
      else
      {
          sprite.data[1] = 0;
          sprite.invisible = FALSE;
      }

      if (sprite.data[0] == SPRITE_ARR_ID_MOVE_SELECTOR1)
          sprite.y2 = sMonSummaryScreen.firstMoveIndex * 16;
      else
          sprite.y2 = sMonSummaryScreen.secondMoveIndex * 16;
}

/** static void DestroyMoveSelectorSprites(u8 firstArrayId) */
export function DestroyMoveSelectorSprites(firstArrayId: any): any {
  let i: any = null;
      for (i = 0; i < MOVE_SELECTOR_SPRITES_COUNT; i++)
          DestroySpriteInArray(firstArrayId + i);
}

/** static void SetMainMoveSelectorColor(u8 which) */
export function SetMainMoveSelectorColor(which: any): any {
  let i: any = null;
      let spriteIds: any =sMonSummaryScreen.spriteIds[SPRITE_ARR_ID_MOVE_SELECTOR1];

      which *= 3;
      for (i = 0; i < MOVE_SELECTOR_SPRITES_COUNT; i++)
      {
          if (i == 0)
              StartSpriteAnim(gSprites[spriteIds[i]], which + 4);
          else if (i == 9)
              StartSpriteAnim(gSprites[spriteIds[i]], which + 5);
          else
              StartSpriteAnim(gSprites[spriteIds[i]], which + 6);
      }
}

/** static void KeepMoveSelectorVisible(u8 firstSpriteId) */
export function KeepMoveSelectorVisible(firstSpriteId: any): any {
  let i: any = null;
      let spriteIds: any =sMonSummaryScreen.spriteIds[firstSpriteId];

      for (i = 0; i < MOVE_SELECTOR_SPRITES_COUNT; i++)
      {
          gSprites[spriteIds[i]].data[1] = 0;
          gSprites[spriteIds[i]].invisible = FALSE;
      }
}

